commit c2588e2b5cf368ed4aa42acf38aa6329dc996cf5
Author: Tim Rühsen <tim.ruehsen@gmx.de>
Date:   Sat Jan 5 22:50:39 2019 +0100

    Improve libidn2_to_ascii_8z_fuzzer

diff --git a/fuzz/libidn2_to_ascii_8z_fuzzer.c b/fuzz/libidn2_to_ascii_8z_fuzzer.c
index 35e2974..7565528 100644
--- a/fuzz/libidn2_to_ascii_8z_fuzzer.c
+++ b/fuzz/libidn2_to_ascii_8z_fuzzer.c
@@ -58,6 +58,29 @@ int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
        for (unsigned it = 0; it < sizeof(flags)/sizeof(flags[0]); it++) {
                if (idn2_to_ascii_8z(domain, &out, flags[it]) == IDNA_SUCCESS)
                        idn2_free(out);
+               if (idn2_to_ascii_lz(domain, &out, flags[it]) == IDNA_SUCCESS)
+                       idn2_free(out);
+       }
+
+       if ((size & 3) == 0) {
+               uint32_t *u32 = (uint32_t *) malloc(size + 4);
+               char *out2 = malloc(64);
+
+               assert(u32 != NULL);
+               assert(out2 != NULL);
+
+               for (unsigned it = 0; it < sizeof(flags)/sizeof(flags[0]); it++)
+                       idn2_to_ascii_4i((uint32_t *) data, size / 4, out2, flags[it]);
+
+               memcpy(u32, data, size);
+               u32[size / 4] = 0;
+
+               for (unsigned it = 0; it < sizeof(flags)/sizeof(flags[0]); it++)
+                       if (idn2_to_ascii_4z(u32, &out, flags[it]) == IDN2_OK)
+                         idn2_free(out);
+
+               free(out2);
+               free(u32);
        }

        free(domain);
